unsafe fn tdefl_compress_normal(mut d: *mut tdefl_compressor) -> mz_bool {
    let mut pSrc: *const mz_uint8 = (*d).m_pSrc;
    let mut src_buf_left: size_t = (*d).m_src_buf_left;
    let flush: tdefl_flush = (*d).m_flush;

    while src_buf_left != 0 || (flush as c_uint != 0 && (*d).m_lookahead_size != 0) {
        let mut len_to_move: mz_uint;
        let mut cur_match_dist: mz_uint;
        let mut cur_match_len: mz_uint;
        let cur_pos: mz_uint;

        let lookahead_size = (*d).m_lookahead_size;
        let dict_size = (*d).m_dict_size;
        let lookahead_pos = (*d).m_lookahead_pos;

        if lookahead_size.wrapping_add(dict_size) >= (TDEFL_MIN_MATCH_LEN as mz_uint).wrapping_sub(1)
        {
            let dict = &mut (*d).m_dict;
            let next = &mut (*d).m_next;
            let hash_tab = &mut (*d).m_hash;

            let mut dst_pos: mz_uint =
                lookahead_pos.wrapping_add(lookahead_size) & TDEFL_LZ_DICT_SIZE_MASK as mz_uint;
            let mut ins_pos: mz_uint =
                lookahead_pos.wrapping_add(lookahead_size).wrapping_sub(2);

            let mut hash: mz_uint = (((dict[(ins_pos & TDEFL_LZ_DICT_SIZE_MASK as mz_uint) as usize]
                as c_int)
                << TDEFL_LZ_HASH_SHIFT as c_int)
                ^ dict[(ins_pos.wrapping_add(1) & TDEFL_LZ_DICT_SIZE_MASK as mz_uint) as usize]
                    as c_int) as mz_uint;

            let max_add = (TDEFL_MAX_MATCH_LEN as mz_uint).wrapping_sub(lookahead_size) as size_t;
            let num_bytes_to_process: mz_uint =
                if src_buf_left < max_add { src_buf_left } else { max_add } as mz_uint;

            let pSrc_end = if !pSrc.is_null() {
                // SAFETY: pSrc points to the current input buffer and num_bytes_to_process
                // is bounded by src_buf_left, so this computed end pointer is within or one
                // past the same allocation.
                unsafe { pSrc.add(num_bytes_to_process as usize) }
            } else {
                ::core::ptr::null()
            };

            src_buf_left = src_buf_left.wrapping_sub(num_bytes_to_process as size_t);
            (*d).m_lookahead_size = lookahead_size.wrapping_add(num_bytes_to_process);

            while pSrc != pSrc_end {
                // SAFETY: pSrc < pSrc_end, and pSrc_end was derived from the available input.
                let c = unsafe { *pSrc };
                // SAFETY: pSrc is advanced within the same valid input allocation.
                pSrc = unsafe { pSrc.add(1) };

                dict[dst_pos as usize] = c;
                if dst_pos < (TDEFL_MAX_MATCH_LEN as c_int - 1) as mz_uint {
                    dict[(TDEFL_LZ_DICT_SIZE as mz_uint).wrapping_add(dst_pos) as usize] = c;
                }

                hash = (hash << TDEFL_LZ_HASH_SHIFT as c_int ^ c as mz_uint)
                    & (TDEFL_LZ_HASH_SIZE as c_int - 1) as mz_uint;
                next[(ins_pos & TDEFL_LZ_DICT_SIZE_MASK as mz_uint) as usize] =
                    hash_tab[hash as usize];
                hash_tab[hash as usize] = ins_pos as mz_uint16;

                dst_pos = dst_pos.wrapping_add(1) & TDEFL_LZ_DICT_SIZE_MASK as mz_uint;
                ins_pos = ins_pos.wrapping_add(1);
            }
        } else {
            let dict = &mut (*d).m_dict;
            let next = &mut (*d).m_next;
            let hash_tab = &mut (*d).m_hash;

            while src_buf_left != 0 && (*d).m_lookahead_size < TDEFL_MAX_MATCH_LEN as mz_uint {
                // SAFETY: src_buf_left != 0, so pSrc points to a readable input byte.
                let c = unsafe { *pSrc };
                // SAFETY: advancing by one remains within the current input allocation.
                pSrc = unsafe { pSrc.add(1) };

                let dst_pos =
                    ((*d).m_lookahead_pos.wrapping_add((*d).m_lookahead_size))
                        & TDEFL_LZ_DICT_SIZE_MASK as mz_uint;

                src_buf_left = src_buf_left.wrapping_sub(1);
                dict[dst_pos as usize] = c;
                if dst_pos < (TDEFL_MAX_MATCH_LEN as c_int - 1) as mz_uint {
                    dict[(TDEFL_LZ_DICT_SIZE as mz_uint).wrapping_add(dst_pos) as usize] = c;
                }
                (*d).m_lookahead_size = (*d).m_lookahead_size.wrapping_add(1);

                if (*d).m_lookahead_size.wrapping_add((*d).m_dict_size)
                    >= TDEFL_MIN_MATCH_LEN as mz_uint
                {
                    let ins_pos =
                        (*d).m_lookahead_pos
                            .wrapping_add((*d).m_lookahead_size.wrapping_sub(1))
                            .wrapping_sub(2);
                    let hash = (((dict[(ins_pos & TDEFL_LZ_DICT_SIZE_MASK as mz_uint) as usize]
                        as c_int)
                        << (TDEFL_LZ_HASH_SHIFT as c_int * 2)
                        ^ (dict[(ins_pos.wrapping_add(1) & TDEFL_LZ_DICT_SIZE_MASK as mz_uint)
                            as usize] as c_int)
                            << TDEFL_LZ_HASH_SHIFT as c_int
                        ^ c as c_int)
                        & (TDEFL_LZ_HASH_SIZE as c_int - 1)) as mz_uint;

                    next[(ins_pos & TDEFL_LZ_DICT_SIZE_MASK as mz_uint) as usize] =
                        hash_tab[hash as usize];
                    hash_tab[hash as usize] = ins_pos as mz_uint16;
                }
            }
        }

        let lookahead_size_now = (*d).m_lookahead_size;
        let dict_size_now = (*d).m_dict_size;
        let max_dict = (TDEFL_LZ_DICT_SIZE as mz_uint).wrapping_sub(lookahead_size_now);
        (*d).m_dict_size = if max_dict < dict_size_now { max_dict } else { dict_size_now };

        if flush as u64 == 0 && (*d).m_lookahead_size < TDEFL_MAX_MATCH_LEN as mz_uint {
            break;
        }

        len_to_move = 1;
        cur_match_dist = 0;
        cur_match_len = if (*d).m_saved_match_len != 0 {
            (*d).m_saved_match_len
        } else {
            (TDEFL_MIN_MATCH_LEN as c_int - 1) as mz_uint
        };
        cur_pos = (*d).m_lookahead_pos & TDEFL_LZ_DICT_SIZE_MASK as mz_uint;

        if (*d).m_flags & (TDEFL_RLE_MATCHES as mz_uint | TDEFL_FORCE_ALL_RAW_BLOCKS as mz_uint) != 0
        {
            if (*d).m_dict_size != 0 && (*d).m_flags & TDEFL_FORCE_ALL_RAW_BLOCKS as mz_uint == 0 {
                let dict = &(*d).m_dict;
                let c = dict[(cur_pos.wrapping_sub(1) & TDEFL_LZ_DICT_SIZE_MASK as mz_uint) as usize];
                cur_match_len = 0;
                while cur_match_len < (*d).m_lookahead_size {
                    if dict[cur_pos.wrapping_add(cur_match_len) as usize] != c {
                        break;
                    }
                    cur_match_len = cur_match_len.wrapping_add(1);
                }
                if cur_match_len < TDEFL_MIN_MATCH_LEN as mz_uint {
                    cur_match_len = 0;
                } else {
                    cur_match_dist = 1;
                }
            }
        } else {
            tdefl_find_match(
                d,
                (*d).m_lookahead_pos,
                (*d).m_dict_size,
                (*d).m_lookahead_size,
                &raw mut cur_match_dist,
                &raw mut cur_match_len,
            );
        }

        if (cur_match_len == TDEFL_MIN_MATCH_LEN as mz_uint
            && cur_match_dist >= (8 as mz_uint).wrapping_mul(1024))
            || cur_pos == cur_match_dist
            || ((*d).m_flags & TDEFL_FILTER_MATCHES as mz_uint != 0 && cur_match_len <= 5)
        {
            cur_match_len = 0;
            cur_match_dist = 0;
        }

        if (*d).m_saved_match_len != 0 {
            if cur_match_len > (*d).m_saved_match_len {
                tdefl_record_literal(d, (*d).m_saved_lit as mz_uint8);
                if cur_match_len >= 128 {
                    tdefl_record_match(d, cur_match_len, cur_match_dist);
                    (*d).m_saved_match_len = 0;
                    len_to_move = cur_match_len;
                } else {
                    (*d).m_saved_lit = (*d).m_dict[cur_pos as usize] as mz_uint;
                    (*d).m_saved_match_dist = cur_match_dist;
                    (*d).m_saved_match_len = cur_match_len;
                }
            } else {
                tdefl_record_match(d, (*d).m_saved_match_len, (*d).m_saved_match_dist);
                len_to_move = (*d).m_saved_match_len.wrapping_sub(1);
                (*d).m_saved_match_len = 0;
            }
        } else if cur_match_dist == 0 {
            tdefl_record_literal(d, (*d).m_dict[cur_pos as usize]);
        } else if (*d).m_greedy_parsing != 0
            || (*d).m_flags & TDEFL_RLE_MATCHES as mz_uint != 0
            || cur_match_len >= 128
        {
            tdefl_record_match(d, cur_match_len, cur_match_dist);
            len_to_move = cur_match_len;
        } else {
            (*d).m_saved_lit = (*d).m_dict[cur_pos as usize] as mz_uint;
            (*d).m_saved_match_dist = cur_match_dist;
            (*d).m_saved_match_len = cur_match_len;
        }

        (*d).m_lookahead_pos = (*d).m_lookahead_pos.wrapping_add(len_to_move);
        (*d).m_lookahead_size = (*d).m_lookahead_size.wrapping_sub(len_to_move);
        let new_dict_size = (*d).m_dict_size.wrapping_add(len_to_move);
        (*d).m_dict_size = if new_dict_size < TDEFL_LZ_DICT_SIZE as mz_uint {
            new_dict_size
        } else {
            TDEFL_LZ_DICT_SIZE as mz_uint
        };

        if (*d).m_pLZ_code_buf
            > (&raw mut (*d).m_lz_code_buf as *mut mz_uint8)
                .wrapping_offset((TDEFL_LZ_CODE_BUF_SIZE as c_int - 8) as isize)
            || ((*d).m_total_lz_bytes > (31 * 1024) as mz_uint
                && (((*d)
                    .m_pLZ_code_buf
                    .offset_from(&raw mut (*d).m_lz_code_buf as *mut mz_uint8)
                    as c_long as mz_uint)
                    .wrapping_mul(115)
                    >> 7)
                    >= (*d).m_total_lz_bytes)
            || (*d).m_flags & TDEFL_FORCE_ALL_RAW_BLOCKS as mz_uint != 0
        {
            (*d).m_pSrc = pSrc;
            (*d).m_src_buf_left = src_buf_left;
            let n = tdefl_flush_block(d, 0);
            if n != 0 {
                return if n < 0 { MZ_FALSE } else { MZ_TRUE };
            }
        }
    }

    (*d).m_pSrc = pSrc;
    (*d).m_src_buf_left = src_buf_left;
    MZ_TRUE
}

